// Throwaway comparison: which laptop workspace hierarchy makes modal guitar practice easiest?
const majorKeys = ['C','G','D','A','E','B','F#','Db','Ab','Eb','Bb','F'];
const minorKeys = ['A','E','B','F#','C#','G#','D#','Bb','F','C','G','D'];
const families = {
  major:{label:'Major', names:['Ionian','Dorian','Phrygian','Lydian','Mixolydian','Aeolian','Locrian'], qualities:['maj7','m7','m7','maj7','7','m7','m7b5']},
  melodic:{label:'Jazz melodic minor', names:['melodic minor','Dorian ♭2','Lydian augmented','Lydian dominant','Mixolydian ♭6','Locrian ♮2','Altered'], qualities:['m(maj7)','m7','maj7#5','7','7','m7b5','m7b5']},
  harmonic:{label:'Harmonic minor', names:['harmonic minor','Locrian ♮6','Ionian ♯5','Dorian ♯4','Phrygian dominant','Lydian ♯2','Super Locrian ♭♭7'], qualities:['m(maj7)','m7b5','maj7#5','m7','7','maj7','dim7']}
};
const romans = ['I','II','III','IV','V','VI','VII'];
function currentFixture(){return fixtures[state.family][state.parent];}
function modesForParent(){let f=families[state.family];return currentFixture().notes.map((note,i)=>[romans[i],note+f.qualities[i],note,f.names[i]]);}
let modes;
function relationship(){
  const f=currentFixture(), parentNotes=f.notes;
  const notes=parentNotes.map((_,i)=>parentNotes[(state.degree+i)%7]);
  return notes.map((note,i)=>({note, interval:f.intervals[state.degree][i], tonic:i===0, chord:i%2===0, characteristic:state.family==='melodic' && state.degree===2 && (i===3 || i===4)}));
}
function roleText(r){return [r.tonic?'tonic':'',r.chord?'chord tone':'',r.characteristic?'distinctive tone':''].filter(Boolean).join(', ') || 'scale tone';}
function roleClasses(r){return `${r.tonic?'tonic ':''}${r.chord?'chord ':''}${r.characteristic?'characteristic':''}`;}
function roleLegend(){return `<div class="role-legend"><span><b class="legend-ring">○</b> tonic</span><span><b class="legend-chord">●</b> chord tone</span><span><b class="legend-characteristic">◆</b> distinctive tone</span></div>`;}
function relationshipStrip(){
  const m=modes[state.degree], roles=relationship(), chord=roles.filter(r=>r.chord).map(r=>r.note).join(' ');
  const explanation=`${state.parent} ${families[state.family].label} supplies the notes; ${m[2]} is the modal tonic. Degrees 1, 3, 5 and 7 give ${chord}, the tones shown for ${m[1]}.`;
  const distinctive=state.family==='melodic' && state.degree===2 ? `Distinctive tones: ${roles[3].note} is #4; ${roles[4].note} is #5 and also a chord tone.` : 'Distinctive tones are not annotated for this mode in the fixture.';
  const context=`<p>${explanation}</p><p>${distinctive} Shared notes alone do not establish harmonic suitability.</p>`;
  return `<section class="panel relationship"><div class="relationship-head"><div><div class="eyebrow">Parent collection · ${state.parent} ${families[state.family].label}</div><h2><span class="modal-label">Modal tonic · ${m[2]}</span> ${m[2]} ${m[3]}</h2></div><div class="chord-summary"><span>Selected chord</span><strong>${m[1]}</strong><span>${chord}</span></div></div><div class="relationship-notes" aria-label="Mode notes, intervals and chord roles">${roles.map(r=>`<div class="relationship-cell" aria-label="${r.note}, interval ${r.interval}, ${roleText(r)}"><span class="relation-note ${roleClasses(r)}">${r.note}</span><span class="interval">${r.interval}</span><span class="role-symbols" aria-hidden="true">${r.chord?'●':'&nbsp;'}${r.characteristic?'◆':''}</span></div>`).join('')}</div><div class="relationship-footer">${roleLegend()}</div>${state.workflow==='Guided'?`<div class="explanation">${context}</div>`:`<details class="explanation"><summary>About these notes</summary>${context}</details>`}</section>`;
}
const names = {A:'Practice desk', B:'Instrument panel', C:'Study workspace'};
const state = {parent:'D', family:'melodic', minorFamily:'melodic', picker:false, degree:2, workflow:'Guided', playing:false, preset:'Clean guitar', volume:70, position:1, tab:'Score'};
const app = document.querySelector('#app');
function variant(){ const v = new URL(location.href).searchParams.get('variant'); return names[v] ? v : 'A'; }
function changeVariant(delta){ const keys = Object.keys(names); const url = new URL(location.href); url.searchParams.set('variant', keys[(keys.indexOf(variant()) + delta + keys.length) % keys.length]); history.pushState({}, '', url); render(); }
function setup(){return `<div class="setup"><div class="field parent-field"><span>Parent key</span><button class="parent-trigger" data-picker aria-haspopup="dialog" aria-expanded="${state.picker}">${state.parent}${state.family==='major'?' major':' minor'} ▾</button>${state.picker?picker():''}</div><label class="field">Scale family <select data-control="family">${Object.entries(families).map(([id,f])=>`<option value="${id}" ${state.family===id?'selected':''}>${f.label}</option>`).join('')}</select></label><div class="field"><span>Practice</span><div class="segmented"><button data-workflow="Guided" class="${state.workflow==='Guided'?'active':''}">Guided</button><button data-workflow="Self-guided" class="${state.workflow==='Self-guided'?'active':''}">Self-guided</button></div></div><label class="field">Position <select data-control="position"><option value="1" ${state.position===1?'selected':''}>Position 1 · frets 1–8</option><option value="5" ${state.position===5?'selected':''}>Position 2 · frets 5–12</option></select></label></div>`}
function picker(){return `<div class="circle-popover" role="dialog" aria-label="Choose parent key"><div class="circle-title">Circle of fifths <span>Outer major · inner minor</span></div><div class="circle-wheel">${majorKeys.map((p,i)=>{const angle=i*Math.PI/6;return ['major','minor'].map((ring,j)=>{const key=j?minorKeys[i]:p, selected=key===state.parent && (state.family==='major')===!j, radius=j?27:43;return `<button data-key="${key}" data-ring="${ring}" data-index="${i}" aria-label="${key} ${ring}" aria-pressed="${selected}" class="circle-key ${ring} ${selected?'selected':''}" style="left:${50+radius*Math.sin(angle)}%;top:${50-radius*Math.cos(angle)}%">${key}${j?'m':''}</button>`}).join('')}).join('')}<div class="circle-center">${state.parent}${state.family==='major'?'':'m'}<small>parent key</small></div></div><div class="circle-help">Relative pairs share major / natural-minor key signatures. Melodic and harmonic minor add alterations.<br>Arrow keys move · Esc closes</div></div>`}
function modeList(){return `<div class="modes">${modes.map((m,i)=>`<button class="mode ${i===state.degree?'active':''}" data-degree="${i}" aria-pressed="${i===state.degree}"><span>${m[0]} · ${m[2]}</span><strong>${m[1]}</strong><span>${m[3]}</span></button>`).join('')}</div>`}
function player(){let m=modes[state.degree];return `<div class="player"><button class="play" data-play>${state.playing?'■ Stop':'▶ Play'}</button><div class="now"><strong>${m[1]}</strong> <span class="muted">· ${m[2]} ${m[3]}</span><div class="noaudio">${state.playing?'SIMULATED PLAYING':'STOPPED'} · NO AUDIO</div></div><label class="field">Preset <select data-control="preset"><option ${state.preset==='Clean guitar'?'selected':''}>Clean guitar</option><option ${state.preset==='Warm keys'?'selected':''}>Warm keys</option><option ${state.preset==='Sine tone'?'selected':''}>Sine tone</option></select></label><label class="field">Volume <input data-control="volume" type="range" min="0" max="100" value="${state.volume}"><span>${state.volume}%</span></label></div>`}
function score(){
  const m=modes[state.degree], roles=relationship();
  return `<div class="section-head"><div><h2>Score sketch</h2><p class="muted small">${m[2]} ${m[3]} · illustrative sequence, not engraved notation</p></div><span class="eyebrow">Illustrative</span></div><svg class="score" viewBox="0 0 500 155" role="img" aria-label="Illustrative schematic sequence: ${roles.map(r=>`${r.note} ${r.interval}, ${roleText(r)}`).join('; ')}"><g stroke="#647168" stroke-width="1">${[42,55,68,81,94].map(y=>`<line x1="20" y1="${y}" x2="480" y2="${y}"/>`).join('')}</g><text x="23" y="87" font-size="58" fill="#d3dcd1">𝄞</text>${roles.map((r,i)=>{let x=105+i*55,y=90-i*8;return `<g><ellipse cx="${x}" cy="${y}" rx="7" ry="5" fill="#d3dcd1"/>${r.tonic?`<circle cx="${x}" cy="${y}" r="11" fill="none" stroke="#91bfe8" stroke-width="2"/>`:''}<text x="${x}" y="119" text-anchor="middle" fill="#d3dcd1" font-size="12">${r.note}</text><text x="${x}" y="137" text-anchor="middle" fill="#e7bf81" font-size="11">${r.chord?'●':''}${r.characteristic?'◆':''}</text></g>`}).join('')}</svg>${roleLegend()}`;
}
function neck(){
  const strings=[['e',4],['B',11],['G',7],['D',2],['A',9],['E',4]], roles=relationship();
  return `<div class="section-head"><div><h2>Guitar neck</h2><p class="muted small">Fixed physical position · ${modes[state.degree][2]} is the modal tonic</p></div><span class="eyebrow">UNREVIEWED PITCH MAP</span></div><div class="fretboard"><div class="neck">${strings.map(([label,pitch])=>`<div class="string">${label}</div>${Array.from({length:8},(_,i)=>{let r=roles.find(role=>currentFixture().chromas[currentFixture().notes.indexOf(role.note)]===(pitch+state.position+i)%12);return `<div>${r?`<span class="note ${roleClasses(r)}" title="${r.note}: ${r.interval}, ${roleText(r)}" aria-label="${r.note}: ${r.interval}, ${roleText(r)}">${r.note}<span class="neck-symbols" aria-hidden="true">${r.chord?'●':''}${r.characteristic?'◆':''}</span></span>`:''}</div>`}).join('')}`).join('')}</div><div class="frets"><span></span>${Array.from({length:8},(_,i)=>`<span>${state.position+i}</span>`).join('')}</div></div>${roleLegend()}<div class="legend">STANDARD TUNING · NOT VALIDATED CAGED</div>`;
}
function header(){return `<div class="topline"><div class="brand">● <span>practice</span> / modal lab</div><div class="muted small">THROWAWAY PROTOTYPE · NO AUDIO</div></div>`}
function heading(title,description){return `<div class="heading"><div><div class="eyebrow">Modal practice / ${state.parent} ${families[state.family].label}</div><h1>${title}</h1><p class="muted">${description}</p></div><div class="muted small">${currentFixture().notes.join(' &nbsp; ')}</div></div>`}
function variantA(){return `${heading('Practice desk','Choose a mode to compare its notes with the selected chord.')}<div class="panel">${setup()}</div>${modeList()}<div class="panel">${player()}</div>${relationshipStrip()}<div class="study-grid"><section class="panel">${score()}</section><section class="panel">${neck()}</section></div>`}
function variantB(){let m=modes[state.degree];return `${heading('Instrument panel','Choose a degree, then focus on the sound in front of you.')}<div class="b-layout"><aside class="b-rail"><div class="eyebrow">Degrees / modes</div>${modeList()}</aside><main class="b-main"><div class="panel">${setup()}</div><div class="panel hero" style="margin-top:12px"><div><div class="eyebrow">${m[0]} degree · modal root ${m[2]}</div><div class="hero-chord">${m[1]}</div><h2>${m[2]} ${m[3]}</h2><p class="muted small">From ${state.parent} ${families[state.family].label}</p>${player()}</div><div class="eyebrow">CURRENT<br>FOCUS</div></div><div class="study-grid"><section class="panel">${score()}</section><section class="panel">${neck()}</section></div></main></div>`}
function variantC(){let m=modes[state.degree];return `${heading('Study workspace','Navigate the harmony on the left; study one surface at a time.')}<div class="c-layout"><aside class="sidebar"><div class="eyebrow">Practice setup</div>${setup()}<div class="eyebrow">Degrees / modes</div>${modeList()}</aside><main class="workspace"><div class="panel">${player()}</div><section class="panel study-panel"><div class="eyebrow">Study surface · ${m[0]} / ${m[1]} / ${m[2]}</div><div class="tabs"><button class="tab ${state.tab==='Score'?'active':''}" data-tab="Score">Score</button><button class="tab ${state.tab==='Neck'?'active':''}" data-tab="Neck">Guitar neck</button></div>${state.tab==='Score'?score():neck()}</section></main></div>`}
function render(){modes=modesForParent();let v=variant(),m=modes[state.degree];app.innerHTML=`<div class="shell">${header()}${({A:variantA,B:variantB,C:variantC})[v]()}<details class="state"><summary>Prototype state</summary><pre>Variant: ${v} — ${names[v]}\nWorkflow: ${state.workflow}\nDegree: ${m[0]} · Chord: ${m[1]} · Modal root: ${m[2]} · Mode: ${m[3]}\nPosition: frets ${state.position}–${state.position+7}\nPlayback: ${state.playing?'simulated playing':'stopped'} (NO AUDIO)\nPreset: ${state.preset} · Volume: ${state.volume}%\nStudy tab: ${state.tab}</pre></details></div>`;document.querySelector('#variant-label').textContent=`${v} — ${names[v]}`;}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(state.picker && !e.target.closest('.parent-field')){state.picker=false;render();return}if(!b)return;if(b.hasAttribute('data-picker')){state.picker=!state.picker;render();if(state.picker) document.querySelector('.circle-key.selected').focus();else document.querySelector('[data-picker]').focus()}else if(b.dataset.key){state.parent=b.dataset.key;state.family=b.dataset.ring==='major'?'major':state.minorFamily;state.picker=false;render();document.querySelector('[data-picker]').focus()}else if(b.dataset.switch)changeVariant(Number(b.dataset.switch));else if(b.dataset.degree!==undefined){state.degree=Number(b.dataset.degree);render()}else if(b.dataset.workflow){state.workflow=b.dataset.workflow;render()}else if(b.hasAttribute('data-play')){state.playing=!state.playing;render()}else if(b.dataset.tab){state.tab=b.dataset.tab;render()}});
document.addEventListener('change',e=>{let key=e.target.dataset.control;if(!key)return;if(key==='family'){const oldMajor=state.family==='major', newMajor=e.target.value==='major';if(oldMajor!==newMajor){const from=oldMajor?majorKeys:minorKeys, to=newMajor?majorKeys:minorKeys;state.parent=to[from.indexOf(state.parent)];}state.family=e.target.value;if(!newMajor)state.minorFamily=state.family;}else state[key]=key==='position'||key==='volume'?Number(e.target.value):e.target.value;render()});
document.addEventListener('keydown',e=>{if(state.picker){if(e.key==='Escape'){e.preventDefault();state.picker=false;render();document.querySelector('[data-picker]').focus();return}if(e.target.matches('[data-key]') && ['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();const i=Number(e.target.dataset.index);const ring=e.target.dataset.ring;const delta=['ArrowRight','ArrowDown'].includes(e.key)?1:-1;document.querySelector(`[data-ring="${ring}"][data-index="${(i+delta+12)%12}"]`).focus();return}return}if(!['ArrowLeft','ArrowRight'].includes(e.key)||e.altKey||e.ctrlKey||e.metaKey||e.shiftKey)return;const el=e.target;if(el.closest('input, textarea, select, [contenteditable]:not([contenteditable="false"])'))return;e.preventDefault();changeVariant(e.key==='ArrowLeft'?-1:1)});
window.addEventListener('popstate',render);
if(!['localhost','127.0.0.1','[::1]','::1'].includes(location.hostname))document.querySelector('#switcher').hidden=true;
render();
